CREATE TABLE P360_DEAD_LETTERS (ID VARCHAR(64) PRIMARY KEY, DLQ VARCHAR(60) NOT NULL, ORIGINAL_QUEUE VARCHAR(60), ORIGINAL_EXCHANGE VARCHAR(60), ORIGINAL_ROUTING_KEY VARCHAR(150), REASON VARCHAR(40), DEATH_COUNT BIGINT NOT NULL, EVENT_ID VARCHAR(36), TYPE VARCHAR(40), ARCHIVED_AT TIMESTAMP WITH TIME ZONE NOT NULL, PAYLOAD CLOB NOT NULL);
CREATE INDEX IDX_DEAD_LETTER_ARCHIVED ON P360_DEAD_LETTERS(ARCHIVED_AT);
